def verifier(assign):
    # Verify and compute the answer m + n + r
    # Check required keys
    required = ['c6','c5','c4','c3','c2','c1','c0','a','b','c','p','A','B','r0','k','t1','t2','n','m','r']
    for key in required:
        if key not in assign:
            # Missing data; cannot verify
            return (False, None)  # missing key
    c6 = assign['c6']; c5 = assign['c5']; c4 = assign['c4']; c3 = assign['c3']; c2 = assign['c2']; c1 = assign['c1']; c0 = assign['c0']
    a = assign['a']; b = assign['b']; c = assign['c']; p = assign['p']; A = assign['A']; B = assign['B']; r0 = assign['r0']
    k = assign['k']; t1 = assign['t1']; t2 = assign['t2']; n = assign['n']; m = assign['m']; rden = assign['r']
    # GCD helper
    def gcd(u, v):
        while v:
            u, v = v, u % v
        return abs(u)
    # Square helpers
    def is_square(nn):
        if nn < 0:
            return False
        s = int(nn ** 0.5)
        return s * s == nn
    def is_squarefree(nn):
        if nn <= 0:
            return False
        ptest = 2
        while ptest * ptest <= nn:
            if nn % (ptest * ptest) == 0:
                return False
            ptest += 1
        return True
    # Recompute coefficients from parameters to validate integrity
    # Q(x) = t^2 + A t + B, t = a x^2 + b x + c
    q = [0]*5
    q[4] = a*a
    q[3] = 2*a*b
    q[2] = b*b + 2*a*c + A*a
    q[1] = 2*b*c + A*b
    q[0] = c*c + A*c + B
    tm = [c - r0, b, a]
    rcoeff = [0]*7
    for i in range(5):
        for j in range(3):
            rcoeff[i+j] += q[i] * tm[j]
    rcoeff = [p*ri for ri in rcoeff]
    if [c0, c1, c2, c3, c4, c5, c6] != rcoeff[:7]:
        # Coefficients mismatch
        return (False, None)
    # Check structural constraints
    if c6 <= 0:
        return (False, None)
    if gcd(abs(b), 2*a) != 1:
        return (False, None)
    # Confirm A,B indeed correspond to roots t1, t2
    if A != -(t1 + t2) or B != t1 * t2:
        return (False, None)
    # t_min
    t_min = c - (b*b)/(4.0*a)
    if not (t2 < t_min and r0 < t_min and t1 > t_min):
        return (False, None)
    # Discriminants: Only t1 should give real x-solutions, with discriminant n; others negative
    D1 = b*b - 4*a*(c - t1)
    D2 = b*b - 4*a*(c - t2)
    Dr = b*b - 4*a*(c - r0)
    if D1 != n or D2 >= 0 or Dr >= 0:
        return (False, None)
    # n must be squarefree and positive
    if not is_squarefree(n) or n <= 0:
        return (False, None)
    # Answer components
    # Root is x = (-b + sqrt(n)) / (2a); here m = -b, r = 2a
    if rden <= 0:
        return (False, None)
    if gcd(abs(m), rden) != 1:
        return (False, None)
    answer = m + n + rden
    return (True, answer)
